package com.oms.channel.platform;

import com.fasterxml.jackson.databind.*;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import javax.annotation.Resource;
import java.time.*;
import java.util.*;
import static com.oms.channel.platform.ChannelPlatformService.map;

/** Fixed official methods, shop capability gates and per-command deduplication. No shop-wide network lock. */
@Service public class RefundPlatformService {
 @Resource JdbcTemplate db;
 @Resource ChannelPlatformService platform;
 @Resource PlatformSecrets secrets;
 @Resource TmallClient client;
 @Resource PlatformInteractionLog logs;
 private static final ObjectMapper JSON=new ObjectMapper();
 static final Map<String,String> METHODS=new LinkedHashMap<>();
 static final Set<String> READ=new HashSet<>(Arrays.asList("LIST","DETAIL","ALLOWED","REASONS","NEGOTIATE_CHECK","NEGOTIATE_CAN","NEGOTIATE_RENDER","PROOF","MESSAGES","ADDRESSES"));
 static{METHODS.put("LIST","taobao.refunds.receive.get");METHODS.put("DETAIL","taobao.refund.get");METHODS.put("ALLOWED","taobao.refund.detail.get");METHODS.put("AGREE_RETURN","taobao.rp.returngoods.agree");METHODS.put("REVIEW","taobao.rp.refund.review");METHODS.put("PAY","taobao.rp.refunds.agree");METHODS.put("PAY_CODE","taobao.rp.refunds.agree");METHODS.put("REFUSE","taobao.refund.refuse");METHODS.put("REFUSE_RETURN","taobao.rp.returngoods.refuse");METHODS.put("REASONS","taobao.refund.refusereason.get");METHODS.put("NEGOTIATE_CHECK","taobao.refund.negotiate.validate");METHODS.put("NEGOTIATE_CAN","taobao.refund.negotiate.canapply");METHODS.put("NEGOTIATE_RENDER","taobao.refund.negotiatereturn.render");METHODS.put("NEGOTIATE_SUBMIT","taobao.refund.negotiatereturn");METHODS.put("PROOF","taobao.refund.dispute.seller.proof.strategy");METHODS.put("MESSAGES","taobao.refund.messages.get");METHODS.put("MESSAGE","taobao.refund.message.add");METHODS.put("CANCEL_FEEDBACK","taobao.rdc.aligenius.sendgoods.cancel");METHODS.put("INTERCEPT","taobao.rp.refund.intercept");METHODS.put("INTERCEPT_FEEDBACK","taobao.refund.smart.deliveryintercept.feedback");METHODS.put("RETURN_LOGISTICS","taobao.rp.returngoods.refill");METHODS.put("ADDRESSES","taobao.logistics.address.search");}
 static String s(Map<String,?> m,String k){return m.get(k)==null?"":m.get(k).toString();}
 static void require(boolean v,String message){if(!v)throw new IllegalArgumentException(message);}
 String company(String c,long channel){List<String> rows=db.queryForList("SELECT company_code FROM t_channel WHERE UPPER(company_code)=UPPER(?) AND channel_id=?",String.class,c,channel);require(rows.size()==1,"店铺不存在或不属于当前公司");return rows.get(0);}
 public List<String> rateKeys(String c,long channel){String company=company(c,channel);List<Map<String,Object>> identities=db.queryForList("SELECT b.expected_shop_id,a.app_key,a.id app_id,a.simulation_mode,a.company_code FROM channel_platform_binding b JOIN channel_platform_app a ON a.company_code=b.company_code AND a.id=b.app_id WHERE b.company_code=? AND b.channel_id=?",company,channel);return identities.isEmpty()?Collections.emptyList():PlatformRateIdentity.keys(identities.get(0));}
 public Map<String,Object> capability(String c,long channel){String company=company(c,channel);Map<String,Object> binding=platform.detail(company,channel);List<Map<String,Object>> rows=db.queryForList("SELECT a.read_enabled,a.write_enabled,a.payment_enabled,a.ignore_code,a.revision,a.payment_expires_at,(a.payment_session_cipher IS NOT NULL AND a.payment_expires_at>NOW() AND a.payment_app_id=b.app_id AND a.payment_seller_id=b.seller_id) payment_authorized FROM channel_refund_access a LEFT JOIN channel_platform_binding b ON b.company_code=a.company_code AND b.channel_id=a.channel_id WHERE a.company_code=? AND a.channel_id=?",company,channel);Map<String,Object> out=map("channel_id",channel,"authorization",binding.get("auth_label"),"authorization_expires_at",binding.get("token_expires_at"),"available",true,"can_query",binding.get("can_query"),"read_enabled",0,"write_enabled",0,"payment_enabled",0,"ignore_code",0,"payment_authorized",false,"revision",0);if(!rows.isEmpty())out.putAll(rows.get(0));out.put("payment_authorized",Arrays.asList("1","true").contains(s(out,"payment_authorized")));out.put("execution_mode",Boolean.TRUE.equals(binding.get("simulation"))?"SIMULATION":"REAL");return out;}
 /** Batch overview returns only public capability flags, never authorization credentials. */
 public List<Map<String,Object>> capabilities(String c){
  Map<String,Map<String,Object>> saved=new HashMap<>();
  for(Map<String,Object> row:db.queryForList("SELECT a.channel_id,a.read_enabled,a.write_enabled,a.payment_enabled,a.ignore_code,a.revision,a.payment_expires_at,(a.payment_session_cipher IS NOT NULL AND a.payment_expires_at>NOW() AND a.payment_app_id=b.app_id AND a.payment_seller_id=b.seller_id) payment_authorized FROM channel_refund_access a LEFT JOIN channel_platform_binding b ON b.company_code=a.company_code AND b.channel_id=a.channel_id WHERE UPPER(a.company_code)=UPPER(?)",c))saved.put(s(row,"channel_id"),row);
  List<Map<String,Object>> out=new ArrayList<>();
  for(Map<String,Object> binding:platform.refundShopSummaries(c)){Map<String,Object> row=map("channel_id",binding.get("channel_id"),"available",true,"authorization",binding.get("auth_label"),"authorization_expires_at",binding.get("token_expires_at"),"can_query",Boolean.TRUE.equals(binding.get("can_query")),"read_enabled",0,"write_enabled",0,"payment_enabled",0,"ignore_code",0,"payment_authorized",false,"revision",0);row.putAll(saved.getOrDefault(s(binding,"channel_id"),Collections.emptyMap()));row.put("payment_authorized",Arrays.asList("1","true").contains(s(row,"payment_authorized")));out.add(row);}
  return out;
 }
 public void access(String c,long channel,Map<String,Object> input,String actor){String company=company(c,channel);platform.detail(company,channel);int read=flag(input,"read_enabled"),write=flag(input,"write_enabled"),pay=flag(input,"payment_enabled"),ignore=flag(input,"ignore_code");require(pay<=write&&write<=read&&ignore<=pay,"请先启用查询、业务操作，再启用退款付款");require(ignore==0||Boolean.TRUE.equals(input.get("ignore_code_confirmed")),"免验证码须由商家明确确认已在平台开通");long revision=Long.parseLong(s(input,"revision"));int changed=revision==0?db.update("INSERT IGNORE INTO channel_refund_access(company_code,channel_id,read_enabled,write_enabled,payment_enabled,ignore_code,updated_by) VALUES (?,?,?,?,?,?,?)",company,channel,read,write,pay,ignore,actor):db.update("UPDATE channel_refund_access SET read_enabled=?,write_enabled=?,payment_enabled=?,ignore_code=?,updated_by=?,revision=revision+1 WHERE company_code=? AND channel_id=? AND revision=?",read,write,pay,ignore,actor,company,channel,revision);require(changed==1,"退款能力设置已变化，请刷新");}
 static int flag(Map<String,Object> input,String key){String value=s(input,key);require(Arrays.asList("0","1").contains(value),"接口启用状态无效");return Integer.parseInt(value);}
 @SuppressWarnings("unchecked") public Map<String,Object> call(String c,long channel,Map<String,Object> body){String company=company(c,channel),action=s(body,"operation"),method=METHODS.get(action);require(method!=null,"不支持的退款平台操作");boolean write=!READ.contains(action);Map<String,Object> capability=capability(company,channel);require(Boolean.TRUE.equals(capability.get("can_query"))&&"1".equals(s(capability,"read_enabled")),"退款查询未启用或店铺授权未就绪");require(!write||"1".equals(s(capability,"write_enabled")),"店铺尚未启用退款业务操作");require(body.get("args") instanceof Map,"平台参数无效");Map<String,String> args=new LinkedHashMap<>();for(Map.Entry<?,?> e:((Map<?,?>)body.get("args")).entrySet()){require(e.getKey() instanceof String&&e.getValue()!=null,"平台参数无效");String key=e.getKey().toString();require(key.matches("[a-z_]{1,64}")&&!Arrays.asList("session","app_key","sign","method","timestamp","access_token").contains(key),"不能覆盖平台协议或凭据");String value=e.getValue().toString();require(value.length()<=700000,"平台参数超出限制");args.put(key,value);}
    if(Arrays.asList("PAY","PAY_CODE").contains(action))require(args.getOrDefault("refund_infos","").matches(s(body,"refund_id")+"\\|[0-9]+\\|[0-9]+(\\|(onsale|aftersale))?"),"每次仅允许当前退款的明确金额与版本");String refund=s(body,"refund_id");require("LIST".equals(action)||"ADDRESSES".equals(action)||refund.matches("[1-9][0-9]{0,19}"),"平台退款单号无效");if(args.containsKey("refund_id"))require(refund.equals(args.get("refund_id")),"退款身份不一致");
    if(Arrays.asList("PAY","PAY_CODE").contains(action)){require("1".equals(s(capability,"payment_enabled"))&&Boolean.TRUE.equals(capability.get("payment_authorized")),"请启用退款付款并完成本店铺子账号授权");require("true".equals(args.get("ignore_code"))=="1".equals(s(capability,"ignore_code")),"免验证码状态须与店铺设置一致");}
    Map<String,String> digestArgs=new TreeMap<>(args);Map<String,byte[]> files=new LinkedHashMap<>();if(args.containsKey("proof_base64")){String encoded=args.remove("proof_base64");byte[] bytes;try{bytes=Base64.getDecoder().decode(encoded);}catch(RuntimeException bad){throw new IllegalArgumentException("凭证图片编码无效");}int maximum=Arrays.asList("REFUSE","REFUSE_RETURN").contains(action)?130000:512000;require(bytes.length>0&&bytes.length<=maximum,"凭证图片超出当前接口大小限制");String field="MESSAGE".equals(action)?"image":"NEGOTIATE_SUBMIT".equals(action)?"negotiate_pics":"refuse_proof";files.put(field,bytes);}
    if(!files.isEmpty())TmallClient.multipart(Collections.emptyMap(),files,"ValidateRefundProof");
    String request=s(body,"request_id"),digest=TmallClient.digest("SHA-256",method+"/"+json(digestArgs));if(write){require(request.matches("[A-Za-z0-9_-]{8,64}"),"平台写操作缺少稳定请求标识");int inserted=db.update("INSERT IGNORE INTO channel_refund_command(company_code,channel_id,request_id,refund_id,method,args_hash,state) VALUES (?,?,?,?,?,?,'RUNNING')",company,channel,request,refund,method,digest);if(inserted==0){Map<String,Object> old=db.queryForMap("SELECT args_hash,state,response_json FROM channel_refund_command WHERE company_code=? AND channel_id=? AND request_id=?",company,channel,request);require(digest.equals(s(old,"args_hash")),"同一请求标识不能用于不同平台内容");if(old.get("response_json")!=null)return JSON.convertValue(read(s(old,"response_json")),Map.class);return map("outcome","UNKNOWN","message","原平台请求正在处理或结果尚未确认，请先查询");}}
        Map<String,Object> log=null;PlatformInteractionLog.Scope scope=null;long start=System.currentTimeMillis();
    try{Map<String,Object> fresh=capability(company,channel);require(Boolean.TRUE.equals(fresh.get("can_query"))&&"1".equals(s(fresh,"read_enabled"))&&(!write||"1".equals(s(fresh,"write_enabled"))),"店铺授权或退款接口设置已变化，停止提交");Map<String,Object> binding=db.queryForMap("SELECT b.*,a.app_key,a.secret_cipher,a.simulation_mode FROM channel_platform_binding b JOIN channel_platform_app a ON a.company_code=b.company_code AND a.id=b.app_id WHERE b.company_code=? AND b.channel_id=?",company,channel);Map<String,Object> context=body.get("log_context") instanceof Map?new LinkedHashMap<>((Map<String,Object>)body.get("log_context")):new LinkedHashMap<>();context.put("category","REFUND");context.put("interface_name",method);context.put("trigger_source",body.getOrDefault("trigger_source","USER"));log=logs.begin(company,channel,((Number)binding.get("app_id")).longValue(),method,"OPERATION","1".equals(s(binding,"simulation_mode"))?"SIMULATION":"REAL","REFUND",s(body,"actor"),context,map("refund_id",refund,"request_id",request));scope=logs.scope(log);
      JsonNode reply;if("1".equals(s(binding,"simulation_mode"))){require(Boolean.TRUE.equals(platform.detail(company,channel).get("simulation")),"模拟平台能力未启用");reply=logs.call(method,args,()->simulate(company,channel,action,refund,args));}else{String token=secrets.decrypt(s(binding,"token_cipher"));if(Arrays.asList("PAY","PAY_CODE").contains(action)){Map<String,Object> access=db.queryForMap("SELECT a.payment_session_cipher,a.payment_expires_at FROM channel_refund_access a JOIN channel_platform_binding b ON b.company_code=a.company_code AND b.channel_id=a.channel_id AND b.app_id=a.payment_app_id AND b.seller_id=a.payment_seller_id WHERE a.company_code=? AND a.channel_id=? AND a.payment_expires_at>NOW() AND a.payment_enabled=1 AND a.write_enabled=1",company,channel);token=secrets.decrypt(s(access,"payment_session_cipher"));}final String credential=token;reply=logs.call(method,args,()->files.isEmpty()?client.api(s(binding,"app_key"),secrets.decrypt(s(binding,"secret_cipher")),credential,method,args):client.apiFiles(s(binding,"app_key"),secrets.decrypt(s(binding,"secret_cipher")),credential,method,args,files));}
      String envelope=(method.startsWith("taobao.")?method.substring(7):method).replace('.','_')+"_response";JsonNode data=reply.path(envelope);if(!data.isObject())throw new TmallClient.Failure("REFUND_RESPONSE_UNKNOWN",true);Map<String,Object> result=map("outcome","RECEIVED","data",JSON.convertValue(data,Map.class));logs.finish(log,"SUCCESS","",map("refund_id",refund,"operation",action),System.currentTimeMillis()-start,null,false);if(write)db.update("UPDATE channel_refund_command SET state='RECEIVED',response_json=? WHERE company_code=? AND channel_id=? AND request_id=?",json(result),company,channel,request);return result;
    }catch(RuntimeException failure){boolean unknown=!(failure instanceof IllegalArgumentException)&&(!(failure instanceof TmallClient.Failure)||((TmallClient.Failure)failure).unknown);String code=failure instanceof TmallClient.Failure?((TmallClient.Failure)failure).code:"VALIDATION_ERROR";Map<String,Object> result=map("outcome",unknown?"UNKNOWN":"FAILED","error_code",code);if(log!=null)logs.finish(log,unknown?"UNKNOWN":"FAILED",code,map("error_code",code),System.currentTimeMillis()-start,null,false);if(write)db.update("UPDATE channel_refund_command SET state=?,response_json=? WHERE company_code=? AND channel_id=? AND request_id=?",result.get("outcome"),json(result),company,channel,request);return result;}finally{if(scope!=null)scope.close();}
 }
 private void simulationState(String c,long channel,String refund,JsonNode current,String status){
  com.fasterxml.jackson.databind.node.ObjectNode node=(com.fasterxml.jackson.databind.node.ObjectNode)current;
  node.put("status",status);String version=current.path("refund_version").asText("0");
  node.put("refund_version",new java.math.BigInteger(version.matches("[0-9]+")?version:"0").add(java.math.BigInteger.ONE).toString());
  java.time.format.DateTimeFormatter format=java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");java.time.LocalDateTime modified=java.time.LocalDateTime.now().withNano(0);
  try{java.time.LocalDateTime old=java.time.LocalDateTime.parse(current.path("modified").asText(),format);if(!modified.isAfter(old))modified=old.plusSeconds(1);}catch(RuntimeException ignored){}
  node.put("modified",modified.format(format));
  db.update("UPDATE channel_refund_sim SET payload=?,modified=? WHERE company_code=? AND channel_id=? AND refund_id=?",json(map("refund_get_response",map("refund",current))),modified.format(format),c,channel,refund);
 }
 private JsonNode simulate(String c,long channel,String action,String refund,Map<String,String> args){
  String method=METHODS.get(action),envelope=(method.startsWith("taobao.")?method.substring(7):method).replace('.','_')+"_response";
  List<String> rows=db.queryForList("SELECT payload FROM channel_refund_sim WHERE company_code=? AND channel_id=? AND refund_id=?",String.class,c,channel,refund);
  Map<String,Object> data=new LinkedHashMap<>();JsonNode current=rows.isEmpty()?JSON.createObjectNode():read(rows.get(0));if(current.has("refund_get_response"))current=current.path("refund_get_response").path("refund");else if(current.has("refund"))current=current.path("refund");
  if("DETAIL".equals(action)){require(!rows.isEmpty(),"模拟库未找到该退款");data.put("refund",current);}
  else if("ALLOWED".equals(action)){
   List<Object> allowed=new ArrayList<>();if(!Arrays.asList("SUCCESS","CLOSED").contains(current.path("status").asText())){allowed.add(map("operation_code","SELLER_AGREE"));allowed.add(map("operation_code","SELLER_REFUSE"));if("BUYER_NOT_RECEIVED".equals(current.path("good_status").asText()))allowed.add(map("operation_code","SELLER_INTERCEPT"));}
   data.put("detail",map("refund_version",current.path("refund_version").asText(),"allowed_operations",map("operation",allowed)));
  }else if("NEGOTIATE_CHECK".equals(action))data.put("valid_result",false);
  else if("LIST".equals(action)){
   int size=Integer.parseInt(args.getOrDefault("page_size","20")),page=Integer.parseInt(args.getOrDefault("page_no","1"));require(size>0&&size<=100&&page>0&&page<=1000,"模拟分页无效");String start=args.get("start_modified"),end=args.get("end_modified");require(start!=null&&end!=null,"模拟查询需要固定修改时间窗口");
   long total=db.queryForObject("SELECT COUNT(*) FROM channel_refund_sim WHERE company_code=? AND channel_id=? AND modified>=? AND modified<=?",Long.class,c,channel,start,end);List<Object> list=new ArrayList<>();
   for(String raw:db.queryForList("SELECT payload FROM channel_refund_sim WHERE company_code=? AND channel_id=? AND modified>=? AND modified<=? ORDER BY modified,refund_id LIMIT ? OFFSET ?",String.class,c,channel,start,end,size,(page-1)*size)){JsonNode node=read(raw);list.add(node.has("refund_get_response")?node.path("refund_get_response").path("refund"):node.has("refund")?node.path("refund"):node);}
   data.put("refunds",map("refund",list));data.put("total_results",total);data.put("has_next",(long)page*size<total);
  }else if("PAY_CODE".equals(action)){data.put("msg_code","SMS_REQUESTED");data.put("succ",true);}
  else if("PAY".equals(action)){
   require(!rows.isEmpty(),"模拟退款不存在");require(!"SUCCESS".equals(current.path("status").asText()),"模拟平台已退款，停止重复付款");
   simulationState(c,channel,refund,current,"SUCCESS");
   // Local SIMULATION fixture fault only; this is not an official refund field or a REAL vendor path.
   if(current.path("_local_test_pay_response_loss").asBoolean(false))throw new TmallClient.Failure("LOCAL_TEST_PAY_RESPONSE_LOST",true);
   data.put("succ",true);data.put("results",map("refund_mapping_result",Collections.singletonList(map("refund_id",refund,"succ",true))));
  }else if("AGREE_RETURN".equals(action)){require(!rows.isEmpty(),"模拟退款不存在");simulationState(c,channel,refund,current,"WAIT_BUYER_RETURN_GOODS");data.put("is_success",true);}
  else if("CANCEL_FEEDBACK".equals(action))data.put("result",map("result_data",map("success",true)));
  else if("INTERCEPT_FEEDBACK".equals(action))data.put("receive_status",true);
  else if("INTERCEPT".equals(action)){/* Accepted request only. Actual goods return requires a warehouse receipt. */}
  else data.put("is_success",true);
  return JSON.valueToTree(map(envelope,data));
 }
 static JsonNode read(String raw){try{return JSON.readTree(raw);}catch(Exception e){throw new IllegalArgumentException("平台数据格式无效");}}
 static String json(Object value){try{return JSON.writeValueAsString(value);}catch(Exception e){throw new IllegalArgumentException("平台结果序列化失败");}}
}
